function scene_routes():array{return array_merge(['/explore/'],array_map(fn($id)=>'/explore/'.$id.'/',array_keys(scenes())));}
function scene_catalog():array{$out=[];foreach(scenes() as $id=>$s)$out[]=['id'=>$id,'url'=>'https://beyondspacetime.org/explore/'.$id.'/']+$s;return $out;}
