function explore_home_section():void{?><section class="section"><div class="section-heading"><div><span class="eyebrow gold">NEW · IMMERSIVE SCIENCE</span><h2>Enter the research universe.</h2></div><a href="/explore/">All 3D explorations →</a></div><p class="lead">Rotate the view, change physical parameters and inspect the actual numerical results. Every scene is a bounded educational control, with the scientific source one click away.</p><div class="grid three"><?php foreach(array_slice(scenes(),0,3,true) as $id=>$s)scene_card($id,$s);?></div></section><?php }
